// ═══════════════════════════════════════════════════════════════════════
// ║ 79t-0-npc-data.js — round 112: the villagers’ proposals (Kris: "The NPCs need to have more personality …"). Made from
// ║ /tmp npc data (Claude). LNPC.N: every NPC (or group), most met first; LNPC.D dramas; LNPC.E engagement ideas; LNPC.A art.
// ═══════════════════════════════════════════════════════════════════════
var LNPC={"N": [{"id": "oswin", "n": "Master Oswin", "role": "Keeper of the Adventurers’ Guild", "where": "Village — the Green, then the guild hall", "meet": 62, "how": "the first walk (8 steps) · his 3 first tasks, given and handed in (6) · a guild visit or two in each realm for quests and rewards (~20) · reminders when you are stuck (~10) · lessons and pop-ups (~8) · story moments and the ending (~10)", "q": "main", "qt": "Main: the first walk and the guild’s quests. Side: his three first tasks (his purse, Old Nell’s net, Pia’s pins).", "ideas": [["The legend who keeps growing his stories", "Boastful · running gag", "Norse <i>mannjafnaðr</i>, the boasting match of the sagas", "Every tale of his adventuring days grows each time he tells it: the troll was as tall as a door, then a house, then \"the size of the longhouse, and it had a cousin\". Villagers correct him behind his back. Late in the game you meet the real troll — it is knee-high and polite."], ["The Varangian drill-master", "Deadpan · stern", "The Varangian Guard of Miklagard (Constantinople), where Norsemen served the emperor", "Once an axe-bearer in the far south, he wants a \"proper report\" for every quest: <i>objective, foes, losses, snacks</i>. He grades your reports. It is funny because he is completely serious — and because he gives you an A only once, at the very end."], ["The mentor with five tankards", "Dark · earnest", "The lost war-bands of the sagas; the drinking-horn shelf of a hall", "Five tankards stand on a shelf in the guild; four are turned upside down. His old band, the Ravens, rode into the Ashlands on the Ash Night and never came back. He does not talk about it — until you bring something of theirs home."]], "arc": [["Grasslands", "Bluff and boastful; drills you, grades your reports, tells the troll story (version 1)."], ["Wetlands", "You find a Raven shield in a sunken site. He goes quiet for the first time and tells you to \"keep it in the guild, out of the rain\"."], ["Highlands", "He tells the true story of the Ash Night: he was the one who stayed behind. The troll story stops growing."], ["Ashlands", "One freed spirit’s memory is a Raven’s. He turns her tankard right side up. One by one, as you find the rest, all five stand up."], ["After the end", "He retires from boasting — and starts telling YOUR story at the tavern, wildly exaggerated (\"…and then the twin punched Surtharn into the SEA\")."]], "side": [["The Five Tankards", "fetch · story", "Raven-feather cloak (item) + 150 g per keepsake", "Find a keepsake of each lost Raven, one per realm (a shield, a horn, a ring, a hood). Each one turns a tankard up and earns a short story about its owner.", "4 keepsake icons; the five-tankard shelf (two states); the Raven-feather cloak", false], ["Proper Paperwork", "delivery · riddle", "150 g + a Hearty Stew", "He seals a report \"for the steed-of-the-sea’s keeper\". The address is a kenning (a Norse riddle-name: sea-steed = ship, so Hesk the Boatwright or Harbormaster Quill). Ask him again and he adds \"the one who builds, not the one who counts\". Rolf at the tavern explains kennings if you ask.", "a sealed report letter icon", true]]}, {"id": "benno", "n": "Benno the Baker", "role": "The merchant — buys your loot, sells bread and food", "where": "Village — the bakery-merchant", "meet": 44, "how": "selling loot after most trips home (~30) · buying food (~10) · a few story lines (~4)", "q": "none", "qt": "None today.", "ideas": [["Relentlessly cheery pun-maker", "Super cheery · puns", "The festival breads of the Norse year; Byzantium’s bakers’ guild (the <i>Book of the Eparch</i> set their prices)", "Bread puns for every moment: \"I knead you to come back safe\", \"that’s the yeast I can do\", \"you’re on a roll\". Gets as excited about your loot as about a perfect crust."], ["The anxious haggler", "Anxious · self-mocking", "The merchants of Novgorod, who kept accounts on birch bark", "Keeps a birch-bark ledger and frets over every coin. When you sell something good he sweats: \"You’ll ruin me! …I’ll take it. I’ll take it.\""], ["The bread philosopher", "Deadpan · earnest", "Old sourdough kept alive for generations", "Treats baking as sacred: \"A loaf is a promise to tomorrow.\" He has kept his sourdough starter, Old Mother, alive since the Ash Night — thirty-six years — and talks to it."]], "arc": [["Grasslands", "Plain loaves. Sighs that there are no children in the village to bake honey cakes for."], ["Wetlands", "Old Mother is failing; he needs marsh rye. Your first chance to help him (side quest)."], ["Highlands", "His rivalry with Morwen breaks out: \"your potions are just liquid bread\". A taste-off on the Green."], ["Ashlands", "He bakes travel bread with the ingredients you bring — food that helps in fights."], ["After the end", "At the celebration he bakes the first honey cakes in thirty-six years — for the first newborns."]], "side": [["Old Mother’s Rescue", "fetch, one realm at a time", "A Runeloaf each time (food: more health for a while) + 80 g", "Save the 36-year starter: marsh rye from the Wetlands, snow-honey from the Highlands, ember-salt from the Ashlands.", "3 ingredient icons; the Runeloaf food icon; Old Mother in her crock (a prop)", false], ["Who Eats the Cakes?", "mystery · riddle", "5 honey cakes + 100 g", "Cakes vanish from the cooling rack each night. Clues: crumbs that glow, tiny footprints, a thread of silk. Ask him again for more clues; Pip or Wren (after the end) or the fairies hint at \"the little folk\". The thief is a hungry fairy.", "glowing crumbs, tiny footprints (props); the cake rack", true]]}, {"id": "morwen", "n": "Morwen the Sorcerer", "role": "The apothecary — potions; sells the Sovereign staff", "where": "Village — the apothecary", "meet": 40, "how": "potions after most trips home (~30) · the Sovereign staff (6,000 g; a Saga step) (~2) · spells and extras (~8)", "q": "main", "qt": "Main: the Sovereign staff (a Saga step).", "ideas": [["The gloomy seeress", "Dark & dismal · dry", "The <i>völva</i>, the Norse seeress with her staff; the dark sayings of the <i>Völuspá</i>", "Every potion comes with a grim prophecy: \"This will heal you. Nothing heals the sky.\" The prophecies are vague — and now and then one accidentally comes true, which annoys her."], ["The Serkland alchemist", "Theatrical · pompous", "The alchemists of Baghdad’s House of Wisdom; the silver of Serkland in Viking hoards", "Learned her craft from traders from the south. Names every potion like a poem (\"the Draught of the Ninth Dawn\" — it is a health potion) and over-explains her methods at length."], ["The one who knew the chains", "Dark · drama", "<i>Seiðr</i>, the old binding magic", "Long ago she learned the binding-song the Binders use. She did not know what it would become. Her potions are penance. Not funny at all — a quiet, heavy secret."]], "arc": [["Grasslands", "The grand alchemist: every potion a poem, every sale a lecture with footnotes. Sells the Sovereign staff \"for a masterpiece of the alchemical art\"."], ["Wetlands", "Talks of her teacher, a silver-tongued trader from Serkland, \"who taught me everything — even what I wish I had not learned.\""], ["Highlands", "The lectures stop for once: in her teacher’s books she once read the binding-song the Binders use. She asks you to ask again another day."], ["Ashlands", "Her answer: the Counter-Verse, a draught that loosens a chain \"the way vinegar loosens rust\" (footnotes enclosed)."], ["After the end", "Nothing left to explain — so she explains anyway, beaming."]], "side": [["Ingredients of Doom", "fetch", "3 greater potions + a new recipe", "Five grim ingredients: bog-lantern moss, a Binder’s cooled ember, crystal dew, an ash-lily, a raven’s feather.", "5 ingredient icons", false], ["The Prophecy of the Third Spoon", "riddle · treasure hunt", "An elixir + 200 g", "\"Where the third spoon stirs and the stone forgets, the gold sleeps.\" Ask her again: \"It was a long night. There may have been porridge.\" Elder Runa recognises the old porridge-stone by the mill; the twin knows \"the stone that forgets\" is the one with a worn-away rune.", "an old spoon icon; a buried cache spot", true]]}, {"id": "twin", "n": "Your twin (Zeldor / Zeldara)", "role": "The one who stays — the scholar in the library", "where": "Village — the library by day, home at night", "meet": 30, "how": "talks in the library as the story moves (~14) · night mumbles (~4) · Godsbane (~4) · the feast hall and the ending (~8)", "q": "main", "qt": "Main: teaches you GODSBANE, comes to Asgard.", "ideas": [["The know-it-all sibling", "Warm · teasing", "The Lawspeaker of Iceland’s Althing, who recited the law from memory", "Corrects your rune pronunciation and keeps a running tally of who the \"real\" hero is (\"Village chores: me 312, you 0\"). Always warm underneath."], ["The scholar with the string wall", "Excitable · scatter-brained", "Irish monk-scribes and their illuminated books", "Rapid-fire deductions; a wall of saga pages joined with string. Sometimes gloriously wrong (\"…so the Binders are allergic to cheese\"), sometimes eerily right."], ["The quiet worrier", "Earnest · tender", "Rune-stones raised for those far away (\"…who went east\")", "Writes you letters you find in your pack after big fights. They stay cheerful on the surface, and you can read the worry underneath."]], "arc": [["Grasslands", "Teasing, keeps score; you’re \"the one who hits things\"."], ["Wetlands", "The string wall begins; the first wrong-but-funny theory."], ["Highlands", "The deductions get scary-accurate (the masked one; the basket)."], ["Ashlands", "The letters: worried, brave."], ["After the end", "Writes the saga of you both — and gives you top billing, grudgingly."]], "side": [["Pages of the Lost Saga", "collect · lore", "100 g per page; all 8 → Scholar’s Ink (more XP from spirits)", "Eight torn pages of the oldest saga are scattered through the sites. Each one is a lore snippet, read aloud by your twin.", "a torn page icon; Scholar’s Ink", false], ["The Unreadable Rune", "riddle · cipher", "A rune charm (a small, lasting buff)", "A line of runes on the library wall uses a letter-swap. Ask your twin again for a letter; Elder Runa and Rolf each know one more.", "the cipher on the wall (prop); the charm icon", true]]}, {"id": "tilda", "n": "Tilda the Merchant", "role": "The general shop", "where": "Village — the shop", "meet": 28, "how": "supplies and ammunition through the game (~24) · lines (~4)", "q": "none", "qt": "None today.", "ideas": [["The cheerfully rude shopkeeper", "Funny-rude", "Market-women of Birka and Hedeby, who wore the house keys at their belt", "Blunt and unimpressed, never cruel: \"That’s the worst haggling I’ve heard since the Ash Night. Fine. Five off.\" Rates your outfit out of ten (never above six)."], ["The gossip hub", "Chatty · nosy", "Market gossip as news before newspapers", "Knows everything about everyone; her rumours become side-quest hints (\"Hesk’s been talking to his planks again…\")."], ["The keeper of keys", "Wry · mysterious", "The keys a Norse housewife carried as a sign of authority", "Has a key for every lock in the village — and one she cannot place. It bothers her more than she admits."]], "arc": [["Grasslands", "Rude to you."], ["Wetlands", "Grudging respect after you bring something rare."], ["Highlands", "A rivalry with Benno: who is the village’s best merchant?"], ["Ashlands", "The mystery key opens something (side quest)."], ["After the end", "Calls you a \"regular\" — her highest honour."]], "side": [["The Key With No Door", "riddle · search", "A rare ring + 120 g", "The key’s bow is cut with a little picture: a wave over a tower. Ask again: \"It’s colder than my shop.\" Hesk or Ilsa recognise it: the lighthouse’s old sea-door.", "the key icon; the sea-door and its chest", true], ["Stock-Taking Day", "delivery", "A day of 10 % off + 80 g", "Three crates were delivered to the wrong buildings. Find and return them before dark.", "3 crate props", false]]}, {"id": "garrick", "n": "Garrick the Blacksmith", "role": "The forge — upgrades and crafting", "where": "Village — the forge", "meet": 26, "how": "upgrades and crafting through the game (~22) · lines (~4)", "q": "none", "qt": "None today.", "ideas": [["The perfectionist grump", "Funny-rude", "Völund (Wayland), the master smith of legend", "Insults your weapon care, never you: \"You’ve been opening jars with this, haven’t you.\" Lovingly fixes it anyway."], ["The forgery hunter", "Pedantic · deadpan", "The famous ULFBERHT swords — and the cheap fakes with the letters in the wrong place", "Obsessed with master’s marks. Spots fakes instantly: \"+VLFBERHT+ — the cross is on the wrong side. Amateurs.\""], ["The smith who will not make chains", "Dark · stern", "The smith-thralls of the sagas", "He was once forced to forge chains. He refuses to make a single link again, even for a gate."]], "arc": [["Grasslands", "Grump."], ["Highlands", "Dunn is freed: dwarf versus human pride — a forge-off."], ["Ashlands", "He and Dunn team up on your best weapon."], ["After the end", "He beats a sword into a ploughshare for the new hamlets."], ["Throughout", "His one rule: no chains."]], "side": [["The False Marks", "hunt", "A master’s upgrade on one weapon", "A wandering trader has sold three fake blades in the realms. Find the buyers and swap the fakes for real ones.", "3 fake blades (icons) with the wrong mark", false], ["Coal for the Cold Forge", "fetch", "120 g + a whetstone (a short sharpness buff)", "Ten lumps of Highland coal before the first frost.", "coal icon; whetstone icon", false]]}, {"id": "brask", "n": "Sergeant Brask", "role": "The armoury", "where": "Village — the armoury", "meet": 18, "how": "armour through the game (~15) · lines (~3)", "q": "none", "qt": "None today.", "ideas": [["All bark, no bite", "Slapstick · contrast", "Drill-masters everywhere", "Shouts every sentence, then whispers the kind part: \"WEAR YOUR HELMET! …it brings out your eyes.\""], ["The homesick Varangian", "Wistful · running gag", "The Varangians’ tales of Miklagard’s wonders", "Compares everything to Miklagard: \"In Miklagard, the armour polishes itself. And the soup sings.\""], ["The rule-quoter", "Deadpan", "The Jomsvikings’ strict code", "Invents a rule for every situation: \"Rule forty-seven: never trust a goat.\""]], "side": [["Rule Forty-Eight", "fetch", "A shield + 100 g", "Goblins stole the pages of his rulebook. Get them back — and find out what Rule 48 is (\"Rule 48: see Rule 47\").", "rulebook pages icon; a goblin camp sign", false], ["A Letter to Miklagard", "delivery", "150 g + a bolt of Miklagard silk (a cape dye)", "Take his letter to Captain Vela’s sky port; it must \"go south with the next good wind\".", "a letter; a silk-bolt icon", false]]}, {"id": "mira", "n": "Mira the Mechanic", "role": "Builder of the Great Scar lift; the hearth trays", "where": "Wetlands tower; then her workshop", "meet": 16, "how": "her rescue (~2) · the four hearth trays, asked and made (~8) · the workshop and the story (~6)", "q": "main", "qt": "Main: rescue, the lift, the four hearth trays.", "ideas": [["The chaotic optimist", "Super cheery · slapstick", "Norse dwarf-craft — and a lot of small explosions", "Everything she builds explodes a little; she celebrates every time: \"It exploded in the RIGHT direction!\""], ["Disciple of the ingenious book", "Earnest · nerdy", "The Book of Ingenious Devices (Baghdad, 9th c.); the emperor’s mechanical singing birds in Miklagard", "Treasures a battered copy of a book of devices from the far south: self-filling cups, a bird that sings by water."], ["The compulsive measurer", "Deadpan", "Builders’ tally-sticks", "Measures everything, including you (\"one Zeldor and a quarter\"), to three decimal places."]], "side": [["The Singing Bird", "fetch", "A mechanical bird that perches on your shoulder (cosmetic) + 200 g", "Three brass gears from the Highlands’ old automatons.", "3 gear icons; the brass bird (small sprite)", false], ["Mira’s Puzzle Box", "riddle · puzzle", "A haste potion + 150 g", "A box that opens only one way. Ask Mira again: \"think like a mill wheel\"; Greta the miller tells you which way the wheel turns.", "the puzzle box (icon and open state)", true]]}, {"id": "coral", "n": "Coral the Island Trader", "role": "Island trader — each realm’s metal for Mira’s trays", "where": "The four harbour islands", "meet": 15, "how": "buying each realm’s metal (~4) · supplies on each isle (~8) · lines (~3)", "q": "main", "qt": "Main: sells each realm’s metal (for Mira’s trays).", "ideas": [["The scale-weigher", "Funny · fussy", "Viking traders weighed hack-silver on folding scales", "Weighs every coin on tiny scales and refuses round numbers: \"Forty-one and a bit. I don’t trust forty.\""], ["The sing-song islander", "Cheery", "The Norse-Gael traders of Dublin and the Hebrides", "Speaks half in rhyme and hums sea songs; every bargain ends in a verse."], ["The \"honest\" smuggler", "Sly · wink-wink", "The tax-dodging traders of every port", "Everything is \"definitely not stolen\". You keep finding the original owners’ names scratched off."]], "side": [["Hack-Silver", "collect", "Rare metal at half price", "Five silver trinkets from shipwrecks on the island beaches.", "5 silver trinket icons; the folding scales (prop)", false], ["Lost Cargo", "search", "3 potions + 120 g", "Three of her barrels floated off in a storm. Find them on the other islands’ shores.", "barrel props", false]]}, {"id": "solveig", "n": "Sólveig the Glasswright", "role": "Fuses the soulglass lattices in the Glimmerhall", "where": "The Glimmerhall", "meet": 14, "how": "meeting her (~2) · turning in shards (~6) · the four lattices (~4) · lines (~2)", "q": "main", "qt": "Main: the four soulglass lattices.", "ideas": [["The singer to glass", "Serene · otherworldly", "Sámi <i>joik</i>, songs that are not about someone but ARE them", "Soft-spoken; sings to the glass as she works, a different song for each spirit’s shard."], ["The brutally honest critic", "Funny-rude", "Glass-bead makers of Ribe judging their beads", "\"This shard is cloudy. Like your judgment.\" She is right, every time."], ["The mosaic dreamer", "Earnest · wistful", "The gold mosaics of Miklagard’s great church", "Dreams of a mosaic of all forty spirits — and starts it, piece by piece, as you free them."]], "side": [["The Forty-Light Mosaic", "collect", "Every 10 pieces: a potion, gold, a glass charm", "Sea-glass in every colour from the beaches; the mosaic on her wall grows as you bring it.", "sea-glass icons; the mosaic wall in 4 stages", false], ["A Song for the Glass", "riddle · listening", "A soulglass charm (a lasting buff)", "\"Bring me the song the wind sings at the top of the Scar.\" Ask her again and she hums the first notes; Ilsa or Hana know the rest.", "a small four-note song prompt (UI)", true]]}, {"id": "rolf", "n": "Rolf the Bartender", "role": "The tavern — food, drink, rest", "where": "Village — the tavern", "meet": 12, "how": "meals and rest (~9) · lines (~3)", "q": "none", "qt": "None today.", "ideas": [["The flyting champion", "Funny-rude · wordplay", "<i>Flyting</i>: the Norse and Scots contest of trading insults in verse (Loki’s flyting in the <i>Lokasenna</i>)", "Challenges you to rhyme-duels, clean and silly: \"Your sword’s so blunt, it apologises to bread.\""], ["The storyteller who can’t end", "Rambling", "The tavern saga-teller", "Tells tavern sagas and never quite reaches the end — \"…and that’s when the goat — wait, where was I?\""], ["The skald with stage fright", "Shy · sweet", "The mead of poetry myth", "Once a skald, froze at a great feast. Writes beautiful verse in secret; reads it only when no one is listening."]], "side": [["Flyting Night", "mini-game", "Skald’s mead (more XP for a while) + 100 g", "A three-round duel of rhymes against tavern regulars: pick the best comeback.", "flyting cards (UI); the tavern stage", false], ["The Mead of Poetry", "fetch", "A special mead (a lasting small buff)", "Honey from the Wetlands, berries from the Highlands, a pinch of ash-salt.", "3 ingredient icons; a mead-horn", false]]}, {"id": "iva", "n": "Iva the Jeweler", "role": "The jeweller — gems and rings", "where": "Village — the jeweller", "meet": 11, "how": "gems and rings (~9) · lines (~2)", "q": "none", "qt": "None today.", "ideas": [["The gem whisperer", "Whimsical", "Gem lore of the north", "Talks to every gem; each has a name and a mood (\"the Sulking Garnet\")."], ["The suspicious one", "Paranoid · funny", "Locked chests of Gotland’s silver hoards", "Sure everyone is a thief; pats your pockets before you leave. Apologises. Pats them again."], ["The coin historian", "Earnest · nerdy", "The Arabic silver coins in Viking hoards, with their Kufic letters", "Collects coins from far away and tells where each came from."]], "side": [["A Buried Hoard", "treasure hunt", "Gems + a ring", "A hoard-map in three clues; each clue a line of verse.", "a hoard-map icon; a hoard chest", false], ["The Sulking Garnet", "riddle", "A rare gem", "Her favourite gem has \"run away\". Ask her again: \"It hates the cold and loves a fire.\" Tilda saw something glint in the forge.", "a garnet icon", true]]}, {"id": "runa", "n": "Elder Runa", "role": "The village elder, keeper of the Runestone", "where": "Village — the Green", "meet": 10, "how": "the first walk and waystones (~4) · old lore through the game (~6)", "q": "tut", "qt": "Tutorial: waystones.", "ideas": [["The mischievous grandmother", "Playful · sly", "<i>Hnefatafl</i>, the Viking board game", "Cheats at hnefatafl and denies it. Tells half-true tales with a wink."], ["The solemn lawspeaker", "Majestic", "The Lawspeaker reciting the law at the Althing", "Speaks old lore in verse; a hush falls when she starts."], ["Forgetful and brilliant", "Scatter-brained · warm", "Grandmothers everywhere", "Calls you by the goat’s name, but remembers every rune ever carved."]], "side": [["Hnefatafl at Dusk", "mini-game", "A rune charm + 100 g", "Best of three on the Green. She cheats; catch her twice and she concedes.", "the board and pieces", false], ["Riddles of the Stones", "riddle contest", "A runic amulet", "Three riddles in the style of King Heidrek’s riddle-contest. Ask her again for a nudge; your twin knows the old answers.", "the amulet icon", true]]}, {"id": "quill", "n": "Harbormaster Quill", "role": "The harbour islands’ harbormaster", "where": "The four harbour islands", "meet": 9, "how": "arriving at each harbour (~4) · boats and lines (~5)", "q": "none", "qt": "None today.", "ideas": [["The shameless real-estate pitch", "Ironic · salesy", "Erik the Red, who named a frozen island Greenland \"so people would want to go there\"", "Renames each isle absurdly (\"Sunny Paradise Isle\", for a rock in a blizzard)."], ["The toll stickler", "Deadpan · bureaucratic", "Harbour tolls at Hedeby", "Forms in triplicate for a rowing boat."], ["The seasick harbormaster", "Self-mocking", "—", "Never sails. Turns green at the word \"wave\"."]], "side": [["Name That Isle", "exploration", "100 g per isle", "Visit the four islands and pick their new names (one honest, one Quill-ish).", "new name-boards for the harbours", false], ["Signals in the Dark", "relay", "2 potions + 150 g", "Carry a lantern-signal between the lighthouse and two harbours before it fades.", "a signal lantern icon", false]]}, {"id": "hana", "n": "Hana the Stable Master", "role": "The stables — horses and mounts", "where": "Village — the stables", "meet": 8, "how": "mounts (~6) · lines (~2)", "q": "none", "qt": "None today.", "ideas": [["Speaks through the horse", "Quirky", "Sleipnir and the horse-lore of the north", "Only talks to you through her horse: \"Biscuit says you’re late.\""], ["The steppe trick-rider", "Competitive", "The horse peoples of the Khazar steppe, on the Vikings’ eastern routes", "Challenges you to races and stunts; terrible loser."], ["The fussing animal-mother", "Super cheery", "—", "Frets over every animal in Runeheim, including monsters."]], "side": [["The Runaway Foal", "chase", "A mount stamina charm", "A foal bolted into the meadows — it dashes, tires and rests (like the animals now), so you can catch up.", "the foal sprite", false], ["Race to the Mill", "timed ride", "120 g + carrots (mount food)", "Beat Hana to the windmill on horseback.", "race flags (props)", false]]}, {"id": "mael", "n": "Sister Mael", "role": "The island well — healing", "where": "The four harbour islands", "meet": 8, "how": "healing at the island wells (~6) · lines (~2)", "q": "none", "qt": "None today.", "ideas": [["The cheerfully morbid nurse", "Dark-funny", "—", "Kind, gentle — and describes your wounds in gleeful detail."], ["The one who forgave", "Serene · earnest", "The Irish monasteries the Norse raided — and the holy wells of Ireland", "From a far shore that was raided long ago; she chose to heal instead of hate."], ["The teller of tiny miracles", "Warm", "Saints’ tales", "A small, strange miracle story with every healing."]], "side": [["Herbs of the Four Isles", "collect", "3 potions + a herb recipe", "A herb from each harbour island.", "4 herb icons", false], ["The Illuminated Page", "fetch", "A blessing (slow healing for a while)", "A painted page from a sunken ruin.", "an illuminated page icon", false]]}, {"id": "nell", "n": "Old Nell the Fisher", "role": "Fisher on the pier", "where": "Village — the pier", "meet": 7, "how": "her net (~4) · lines (~3)", "q": "side", "qt": "Side: Old Nell’s net.", "ideas": [["The tall-tale fisher", "Boastful · deadpan", "Thor fishing for the World Serpent with an ox head", "Swears she once hooked the World Serpent with an ox head: \"Bit through my line. Rude.\""], ["The grumpy patient one", "Funny-rude · terse", "—", "\"Fish don’t talk. Neither should you.\""], ["The weather-witch", "Eerie", "Weather lore of the fishing villages", "Predicts weather by her knees; always right."]], "side": [["The Ox-Head Bait", "fetch · fishing", "A trophy fish for your home + fish stew", "Bring an ox skull for \"the one that got away\".", "an ox-skull icon; the trophy fish (a wall prop)", false], ["The Fishing Contest", "mini-game", "A rod upgrade + 100 g", "Out-fish Nell from the pier.", "fish icons; a rod", false]]}, {"id": "holt", "n": "Ranger Holt", "role": "Island guide", "where": "The four harbour islands", "meet": 6, "how": "island tips (~4) · lines (~2)", "q": "none", "qt": "None today.", "ideas": [["The paranoid survivalist", "Funny · nervous", "—", "Whispers, sees ambushes in every bush. Once right."], ["The silent tracker", "Deadpan", "Kalevala woodsmen; Sámi trackers", "Speaks in single words and long nods."], ["The Vinland dreamer", "Wistful", "Leif Erikson’s voyage to Vinland", "Wants to sail past the edge of every map."]], "side": [["Track the White Stag", "tracking", "A hunter’s bow", "Follow its tracks across one isle.", "the white stag sprite; tracks", false], ["Beyond the Map", "exploration", "150 g", "Reach three unexplored corners of the islands.", "map-corner marks", false]]}, {"id": "pell", "n": "Pell the Tailor", "role": "The tailor — clothing", "where": "Village — the tailor", "meet": 6, "how": "clothing (~4) · lines (~2)", "q": "none", "qt": "None today.", "ideas": [["The fashion snob", "Funny-rude", "—", "\"That cape is a cry for help.\""], ["The silk romantic", "Dreamy", "Byzantine silk, prized by the Norse", "Swoons over silk from the far south."], ["The nervous perfectionist", "Anxious", "—", "Measures three times, stammers, never quite finishes."]], "side": [["Sky-Silk", "fetch", "A cape dye (cosmetic)", "A bolt of silk from Vela’s sky port.", "silk-bolt icon", false], ["Patterns of the Spirits", "collect", "A patterned cloak (cosmetic)", "Tablet-weave patterns remembered by freed spirits.", "pattern swatch icons", false]]}, {"id": "pia", "n": "Tumbler Pia", "role": "The acrobat who teaches the roll", "where": "The meadow north of the village", "meet": 5, "how": "the roll lesson (~4) · lines (~1)", "q": "side", "qt": "Side: the Tumbler’s Lesson (the roll).", "ideas": [["The hyperactive acrobat", "Super cheery", "Jugglers and tumblers of the Norse halls", "Talks while flipping; never stands still."], ["The prankster", "Mischievous", "Loki, the trickster", "Swaps your sword for a carrot for one swing."], ["The Hippodrome star", "Theatrical", "The Hippodrome of Miklagard and its rival Blues and Greens", "Once performed for an emperor; still bows after everything."]], "side": [["Pin Hunt II", "search · agility", "Acrobat’s boots (faster roll recovery)", "Her pins, now in harder places — on ledges, past gaps.", "more painted pins", false], ["The Greatest Show", "gather", "200 g + a festival on the Green", "Gather performers (Rolf, Brask, Corr) for a show.", "festival props", false]]}, {"id": "vela", "n": "Captain Vela", "role": "Sky captain — the passes over the Ember Wall; the sky ports", "where": "Ashlands tower; then the sky ports", "meet": 4, "how": "her rescue and the passes (~3) · the sky ports (~1)", "q": "main", "qt": "Main: rescue; opens the sky ports.", "ideas": [["Narrates her own legend", "Theatrical", "Leif Erikson and the far-sailing captains", "Keeps a \"captain’s log\" out loud: \"Day one of my rescue. The hero is late.\""], ["Afraid of heights", "Ironic · self-mocking", "—", "A sky captain who never looks down. Ever."]], "side": [["The Sky Race", "timed flight", "A sky-mount saddle + 200 g", "Race her between three sky ports.", "race rings in the sky", false], ["The Lost Spyglass", "riddle · search", "A spyglass (see farther on the map)", "\"I dropped it where the fire meets the frost.\" Ask again: \"high, very high\". Dunn knows that spot: the Ember Wall’s snowy pass.", "spyglass icon", true]]}, {"id": "bram", "n": "Bram the Builder", "role": "Built the Silverrun bridge", "where": "Grasslands tower; then the bridge", "meet": 4, "how": "his rescue and the bridge (~3) · a line later (~1)", "q": "main", "qt": "Main: rescue; the Silverrun bridge.", "ideas": [["Insufferably right", "Smug · funny", "The builders of the Danevirke and the stave churches", "Measures by eye and is always right; mentions it often."], ["The work-song singer", "Super cheery", "Work songs of the north", "Sings a verse for every plank — badly, happily."]], "side": [["A Bench on the Green", "build", "A bench where you rest faster + 100 g", "Timber from the woods for a bench by the Runestone.", "the bench prop", false], ["Bridge Inspection", "riddle", "A builder’s hammer (weapon)", "\"One stone is a liar.\" Find the false rune-stone on the bridge. Ask again: \"It’s the one that doesn’t hum.\" Hesk knows the sound.", "a false stone (prop)", true]]}, {"id": "dunn", "n": "Dunn the Dwarf Forger", "role": "Built the iron bridge over the Cinder Chasm", "where": "Highlands tower; then the chasm", "meet": 4, "how": "his rescue and the bridge (~3) · a line later (~1)", "q": "main", "qt": "Main: rescue; the Cinder Chasm bridge.", "ideas": [["Blames the fly", "Funny · running gag", "The dwarves Brokk and Eitri: Thor’s hammer came out short-handled because a fly (Loki) bit the bellows-boy", "Every flaw in anything is the fault of \"a fly\". There was no fly."], ["Keeper of grudges", "Grumpy", "Dwarf pride in the old tales", "Ties a knot in a cord for every slight; the cord is very long. Unties one for you."]], "side": [["The Forge-Off", "contest", "An upgraded weapon from both smiths", "Judge Dunn against Garrick — the loser makes the dinner.", "the contest props; two finished blades", false], ["Swat the Forge-Fly", "silly hunt", "A fly-swatter (a joke weapon) + 150 g", "There really is a fly this time. Catch it before it ruins the bridge’s last rivet.", "a buzzing fly sprite", false]]}, {"id": "odin", "n": "Odin", "role": "The Allfather — freed in the feast hall", "where": "Asgard; the village after the end", "meet": 3, "how": "the feast hall, the truth and the farewell (~3)", "q": "main", "qt": "Main: the ending.", "ideas": [["Weary wisdom, and dad jokes", "Warm · wry", "The <i>Hávamál</i>, the sayings of the High One", "Ancient, kind, tired — and fond of terrible jokes, which his raven never laughs at."], ["The riddle-master", "Sly", "Odin’s riddle-contest with the giant Vafthrudnir", "After the end, he offers a riddle-contest. He always wins the last riddle — it is about himself."]], "side": [["The Riddle-Contest", "riddle contest", "Gungnir’s shadow (a cosmetic spear glow)", "After the end, at the Runestone: five riddles; ask the twin or Runa for hints.", "—", true], ["The Ravens’ Errands", "delivery", "A raven familiar look (cosmetic)", "His ravens carry messages to the hamlets; you fetch the replies.", "a raven sprite; letters", false]]}, {"id": "freya", "n": "Freya", "role": "The Lady of the Fields — freed in the feast hall", "where": "Asgard; the village after the end", "meet": 3, "how": "the feast hall, the truth and the farewell (~3)", "q": "main", "qt": "Main: the ending.", "ideas": [["Joyful and fierce", "Super cheery · fierce", "Freya of the myths, whose chariot is drawn by two cats", "Laughs loudly, fights fiercely, loves cats."], ["The spring-bringer", "Serene", "Fólkvangr, her fields", "Every word she says, something blooms nearby."]], "side": [["Her Two Cats", "search", "A falcon-feather cape (cosmetic)", "After the end, her chariot-cats wander Runeheim. Find both.", "two big grey cats (sprites)", false], ["Twelve Flowers", "planting", "A flower crown (small regen)", "Plant a flower in each hamlet.", "flower icons", false]]}, {"id": "corr", "n": "Watchman Corr", "role": "Guard at the village gate", "where": "Village — the gate", "meet": 3, "how": "lines at the gate (~3)", "q": "none", "qt": "None today.", "ideas": [["Writes awful love poems", "Romantic · funny", "The love verses of the skald Kormák", "Secretly loves Ilsa at the lighthouse; his poems rhyme \"lighthouse\" with \"fight mouse\"."], ["The password guard", "Deadpan", "—", "Asks for a password that changes daily. He forgets it too."]], "side": [["A Poem for Ilsa", "delivery · choice", "100 g + a friendship (both)", "Carry his poem — and pick which lines to \"fix\" on the way.", "a folded poem icon", false], ["Today’s Password", "riddle", "A guard’s helmet", "The password is a riddle’s answer; ask him again for another clue, or Tilda (she knows everything).", "—", true]]}, {"id": "marta", "n": "Marta the Cart Vendor", "role": "The vegetable cart", "where": "Village — the market carts", "meet": 3, "how": "lines (~3)", "q": "none", "qt": "None today.", "ideas": [["The hard sell", "Funny-rude", "Market criers", "Shouts prices at you as you pass: \"YOU. You look hungry. And poor. Two coppers.\""], ["The river trader", "Wistful", "The Rus traders on the Dnieper and Volga", "Once sailed the eastern rivers to the great cities; tells their wonders."]], "side": [["The Lost Wheel", "fetch", "A basket of vegetables (food) + 60 g", "Her cart wheel rolled away down the hill.", "a cart wheel prop", false], ["The Apple Run", "delivery", "Apples (food)", "Deliver a crate of apples to three houses before they bruise.", "an apple crate", false]]}, {"id": "g_monarchs", "n": "The fairy monarchs", "role": "Ancient fairy kings and queens of the henges", "where": "Henges in the Wetlands, Highlands and Ashlands", "meet": 3, "count": 3, "how": "each: the meeting, the trial, the farewell (~3)", "q": "side", "qt": "Side: their trials (each adds a familiar slot).", "ideas": [["Speak only in riddles", "Eerie · ancient", "Canon: they never name the gods", "Every line is a riddle; they hint at \"the one with the spear and the one with the falcon cloak\"."], ["Bickering old royals", "Funny", "Old royal rivalries", "Three monarchs who have argued for a thousand years about whose henge is prettiest."]], "side": [["The Monarchs’ Feast", "gather", "A familiar treat (familiar boost)", "Bring each a gift from another’s realm — they pretend not to like it.", "3 gift icons", false], ["The Riddle of the Rings", "riddle", "A fairy charm", "A riddle that spans all three henges; each monarch gives one third of the answer.", "—", true]]}, {"id": "tob", "n": "Tob the Farmer", "role": "The vegetable plots", "where": "Village — the fields", "meet": 2, "how": "lines (~2)", "q": "none", "qt": "None today.", "ideas": [["Names his vegetables", "Cheery · whimsical", "—", "\"This is Sigurd. He’s a turnip.\""], ["The weather doom-sayer", "Dark & dismal", "—", "Every cloud is the end of the harvest. The harvest is always fine."]], "side": [["Crows and Goblins", "defend", "Vegetables (food) + 80 g", "Chase off the crows (and one goblin) from his rows.", "crow sprites", false], ["The Giant Turnip", "pulling mini-game", "A giant turnip stew (big food)", "It needs three people to pull — find two helpers.", "a giant turnip prop", false]]}, {"id": "greta", "n": "Greta the Miller", "role": "The windmill", "where": "Village — the windmill", "meet": 2, "how": "lines (~2)", "q": "none", "qt": "None today.", "ideas": [["The wind superstitions", "Eerie · funny", "Sailors’ and millers’ wind lore", "Never whistle near the mill — \"you’ll call a gale\"."], ["The floury gossip", "Cheery", "—", "Covered in flour; knows the village news before Tilda."]], "side": [["The Stuck Wheel", "riddle · repair", "Flour (Benno pays 100 g for it)", "The gears are in the wrong order; ask her again for the rhyme that tells which turns first.", "gear icons", true], ["Flour for Benno", "delivery", "A loaf + 60 g", "Carry sacks to the bakery.", "flour sack", false]]}, {"id": "hesk", "n": "Hesk the Boatwright", "role": "The boathouse", "where": "Village — the boathouse", "meet": 2, "how": "lines (~2)", "q": "none", "qt": "None today.", "ideas": [["Hears the planks sing", "Whimsical", "—", "\"This one’s a tenor.\" He is very serious about it."], ["Rival of Bram", "Grumpy", "Shipwrights versus house-builders", "Thinks bridges are \"boats that gave up\"."]], "side": [["Singing Wood", "fetch", "A small boat for the lake (cosmetic) + 100 g", "A plank of wood that sings, from the Fairy-Ring Meadows.", "a glowing plank", false], ["The Launch", "festival", "150 g + a boat race", "Help launch his new boat on Mirror Lake.", "the boat; bunting", false]]}, {"id": "fenwick", "n": "Old Fenwick", "role": "The lamplighter", "where": "Village — the lamps at dusk", "meet": 2, "how": "lines (~2)", "q": "none", "qt": "None today.", "ideas": [["Dark and dismal", "Dark · poetic", "—", "\"Every lamp I light is a small argument with the dark. I am losing.\""], ["The night-owl philosopher", "Dry", "—", "Never sleeps; asks you questions no one can answer."]], "side": [["Light the Green", "timed night run", "A lantern (light in dark sites)", "Light every lamp on the Green before the bell.", "lamp-lit states", false], ["The Lantern-Moth", "search", "A moth companion (cosmetic glow)", "His glowing moth escaped — follow its light at night.", "a glowing moth sprite", false]]}, {"id": "ilsa", "n": "Ilsa the Lighthouse Keeper", "role": "The lighthouse", "where": "Village — the lighthouse", "meet": 2, "how": "lines (~2)", "q": "none", "qt": "None today.", "ideas": [["Lonely and poetic", "Melancholy · gentle", "—", "Talks to ships that never come. Has no idea Corr is in love with her."], ["The star-lore keeper", "Serene", "Norse star names and sea-navigation", "Names every star and tells its tale."]], "side": [["Oil for the Light", "fetch", "2 potions + 100 g", "Glow-moss from the Wetlands for the lamp.", "glow-moss icon", false], ["The Star Chart", "riddle", "A star charm (see farther at night)", "Match the stars to their old names; ask her again for one, or the twin for another.", "a star chart", true]]}, {"id": "pip", "n": "Pip", "role": "A child — born after the end", "where": "Village — the fountain (after the end)", "meet": 2, "how": "after the end (~2)", "q": "none", "qt": "None today.", "ideas": [["Endless why-questions", "Cheery", "—", "\"Why is the sky? Why are you? Why?\""], ["Plays twins", "Funny", "—", "Plays at being you, badly. Always makes Wren be the other one."]], "side": [["Hide and Seek", "mini-game", "A wooden toy (home decoration)", "Find Pip in the village.", "—", false], ["The Lost Kite", "search", "Honey cakes", "His kite is stuck in a tree.", "a kite prop", false]]}, {"id": "wren", "n": "Wren", "role": "A child — born after the end", "where": "Village — the market carts (after the end)", "meet": 2, "how": "after the end (~2)", "q": "none", "qt": "None today.", "ideas": [["The tiny entrepreneur", "Funny", "—", "Sweeps for apples and charges for advice."], ["The fearless explorer", "Bold", "—", "Wants to go everywhere you have been. Tomorrow."]], "side": [["To the Lighthouse", "escort", "Shells (home decoration)", "Walk her safely to Ilsa’s lighthouse.", "—", false], ["Shell Collection", "collect", "A shell necklace (cosmetic)", "Ten shells from the lake shore.", "shell icons", false]]}, {"id": "g_fairies", "n": "The fairies", "role": "Twenty fairies, five per realm", "where": "All four realms", "meet": 2, "count": 20, "how": "each: an errand or trial (~2)", "q": "side", "qt": "Side: errands and trials (teach your familiar skills).", "ideas": [["One obsession each", "Whimsical", "—", "One collects buttons, one only rhymes, one is afraid of mushrooms — a single quirk each."], ["Hidden-folk manners", "Eerie · funny", "The Icelandic <i>huldufólk</i>: never throw stones, always greet the rocks", "They are offended by bad manners: throw a stone near them and they sulk for a day."]], "side": [["The Fairy Post", "delivery", "A potion per letter", "Carry letters between fairies of different realms.", "fairy letter icon", false], ["A Gift for Each", "collect", "A fairy-dust charm", "Each fairy wants one strange thing (a button, a snail shell…).", "20 tiny item icons (2 sheets)", false]]}, {"id": "g_teachers", "n": "The castle wardens and teachers", "role": "Twelve island castles; each teaches a skill", "where": "The castle isles", "meet": 2, "count": 12, "how": "each: the castle’s end and the lesson (~2)", "q": "side", "qt": "Side: each castle teaches a skill (the first castle is a Saga step).", "ideas": [["Twelve fighting schools", "Varied", "Varangian axe-men, Rus <i>druzhina</i>, Irish <i>fianna</i>, the horsemen of al-Andalus, Sámi trackers…", "Each teacher comes from a different school and fights like it."], ["Grudging fans", "Funny", "—", "The wardens you beat become your loudest fans and write you letters."]], "side": [["Trials of Mastery", "combat trial", "A stronger version of the skill", "Come back and pass a harder trial with the skill they taught.", "—", false], ["The Wardens’ Cup", "tournament", "A trophy + 300 g", "A tournament of all the wardens you have beaten.", "a trophy prop", false]]}, {"id": "g_great", "n": "The great spirits (Hildr and three more)", "role": "The four greatest spirits, each kept by a realm’s cruellest Binder", "where": "The deepest holds", "meet": 2, "count": 4, "how": "each: freed, and the gift (~2)", "q": "main", "qt": "Main: each gives a great gift (Hildr: Grovesoul).", "ideas": [["Regal and ancient", "Majestic", "The barrow-queens of the sagas", "Speak like the queens they were."], ["Confused by the present", "Funny", "—", "Thirty-six years asleep: \"Who is this Benno, and why is his bread so soft?\""]], "side": [["The Royal Hoard", "treasure hunt", "A great treasure", "Each tells where her hoard is buried — in verse.", "a hoard chest", true], ["A Message for Kin", "delivery", "A royal ring", "Find her living kin among the hamlet folk (after the end).", "—", false]]}, {"id": "g_spirits", "n": "The forty spirits", "role": "Freed spirits of Runeheim", "where": "Bindstones; then the Green", "meet": 2, "count": 40, "how": "each: seen chained, then freed (~2)", "q": "main", "qt": "Main: free six per realm.", "ideas": [["One memory, one wish", "Bittersweet", "Canon: each gives one memory", "Each also has one small wish — to be granted before they go home."], ["Their trades", "Varied", "—", "Weavers, shipwrights, net-menders: each talks like their trade."]], "side": [["Unfinished Business", "small wishes", "A shard of soulglass + a story", "A small wish each — e.g. Asa’s twenty birth-shawls, given to the first newborns at the celebration.", "a few wish items (shawl, toy, letter)", false], ["Lines Home", "escort", "—", "Walk a freed spirit to the Green and hear its story.", "—", false]]}, {"id": "g_mages", "n": "The mage-tower mages", "role": "Sixteen tower mages; each gives a spell", "where": "The mage towers", "meet": 1, "count": 16, "how": "each: the fight and the spell (~1)", "q": "side", "qt": "Side: a spell from each tower.", "ideas": [["Pen-pals after defeat", "Funny", "—", "After you beat them, they send letters full of magical gossip."], ["An academy rivalry", "Pompous", "—", "They rank each other; they all secretly want your vote."]], "side": [["A Rare Reagent", "fetch", "A spell upgrade", "Each mage wants one reagent from a realm that is not theirs.", "reagent icons", false], ["The Mages’ Ranking", "vote", "A mage’s robe", "Vote for the best mage; the losers sulk in their letters.", "—", false]]}, {"id": "g_hamlet", "n": "The hamlet folk", "role": "Forty kin of the spirits, after the end", "where": "The new hamlets", "meet": 1, "count": 40, "how": "each: met after the end (~1)", "q": "none", "qt": "None today.", "ideas": [["Kin of the spirits", "Warm", "—", "Each carries on their spirit’s trade and remembers them."], ["Hamlet rivalries", "Funny", "The Althing, where disputes were argued", "The hamlets compete over everything — best cheese, best goat."]], "side": [["Deliveries", "delivery", "Gold and local food", "Carry goods between hamlets.", "—", false], ["The Hamlet Moot", "vote", "A banner for your home", "Settle a hamlet dispute at a little moot.", "—", false]]}], "D": [["bread", "The Bread and the Brew", "Comedy · a rivalry", "Benno and Morwen, feuding over whose food heals better (\"liquid bread\" against \"solid potion\"). Taste-offs on the Green, small sabotage, villagers taking sides. It ends at the celebration with a joint recipe: potion-bread.", "Benno · Morwen · Tilda · Rolf", "Old Mother’s Rescue; Ingredients of Doom; a Taste-Off side quest"], ["tankards", "The Five Tankards", "Mystery · drama", "Oswin’s lost Ravens, rode into the Ashlands on the Ash Night. A thread through all four realms: keepsakes, a spirit’s memory, and the tankards turned up one by one.", "Oswin · the spirits · Rolf", "The Five Tankards"], ["letters", "Letters to the Lighthouse", "Romance comedy (grown-ups)", "Watchman Corr loves Ilsa and writes terrible poems. You carry them; Pell sews a gift; Rolf coaches him in verse. She finally answers at the celebration.", "Corr · Ilsa · Pell · Rolf", "A Poem for Ilsa; Oil for the Light"], ["moot", "The Village Moot", "Politics, small and funny", "Once per realm the village holds a moot (like Iceland’s Althing). The folk lobby you; your vote changes something small: a statue on the Green, a lamp on the road, which shop has a sale.", "Runa · Tilda · Benno · Brask · Greta", "a vote at each realm’s turn; the Hamlet Moot after the end"], ["thief", "The Thief in the Night", "Mystery · riddles", "Things vanish around the village: Benno’s cakes, Iva’s garnet, Tilda’s key, Nell’s floats. A chain of riddle clues, with hints from different villagers, leads to a hidden-folk family living under the Green who only \"borrowed\" them.", "Benno · Iva · Tilda · Nell · the fairies", "Who Eats the Cakes?; The Sulking Garnet; The Key With No Door"], ["smiths", "The Smith and the Dwarf", "Rivalry to friendship", "Garrick and Dunn: human pride against dwarf pride, a forge-off in each realm after Dunn is freed. They finish as partners, forging your best weapon together.", "Garrick · Dunn · Bram", "The Forge-Off; The False Marks"], ["chains", "Morwen’s Chains", "Dark drama · redemption", "Morwen once taught the binding-song. Her secret comes out slowly; she writes the counter-song that helps you free the great spirits.", "Morwen · the great spirits · Runa", "Ingredients of Doom; the counter-song potion"], ["saga", "The Twins’ Saga", "A frame story", "Your twin writes your saga as you go, and asks the villagers for their part. At the end Rolf performs it at the celebration (badly, with feeling).", "Your twin · Rolf · everyone", "Pages of the Lost Saga; testimonies from each villager"]], "E": [["hearts", "Friendship hearts", "A heart meter (0–5) for each villager. Gifts raise it — each has a love and a hate (Norse custom: a gift calls for a gift). Their lines and prices change as hearts rise."], ["riddle", "Riddle quests with a hint ladder", "A 🧩 quest asks a riddle. Ask the giver again for up to three hints (the reward shrinks a little each time), or ask the \"knowers\" — Runa, your twin, Rolf, Tilda — who each know one piece. Answers are given by picking or bringing the right thing, not typing."], ["barks", "Passing remarks", "Villagers comment as you pass: your new armour, the weather, the time of day, the last boss you beat."], ["rumours", "A rumour board in the tavern", "Rolf’s gossip unlocks side quests; one rumour per trip home."], ["ravens", "Raven post", "After big moments, letters arrive in your pack: thanks, jokes, new requests."], ["schedules", "Day and night routines", "Villagers keep hours: Fenwick lights lamps at dusk, the tavern fills at night. Some quests only at night."], ["minigames", "Mini-games", "Flyting (Rolf), hnefatafl (Runa), fishing (Nell), baking (Benno), arm-wrestling (Brask), horse racing (Hana)."], ["moot", "The village moot", "A small vote at each realm’s turn (drama 4)."], ["portraits", "Faces in the dialogue box", "A painted portrait with four expressions (calm, happy, cross, sad) for the top 20, beside their words."], ["codex", "A page per villager in the Tome", "Fills as you learn about them: their quirk, their story, their arc so far."], ["dailies", "Small daily favours", "Carry water, deliver bread: a little gold or food, a heart now and then."], ["choice", "Pick your reward", "Some quests let you pick one of two rewards (gold or an item)."], ["cameo", "A villager comes along", "For one quest each: Brask fights beside you, Mira repairs a lift on the spot, Hana lends a horse."], ["react", "The village changes", "Villagers move and change after Saga steps — Oswin’s tankards, Benno’s honey cakes, Morwen smiling."]], "A": [["portraits", "Dialogue portraits", "The top 20 villagers in 4 expressions each (calm, happy, cross, sad): about 14 sheets of 6.", "~14"], ["questitems", "Quest items", "About 45 icons: keepsakes, keys, letters, Old Mother’s crock, ingredients, gears, sea-glass, pages, silver trinkets, pins, shells… — 8 sheets of 6.", "~8"], ["props", "New props in the village", "The five-tankard shelf (2 states), the rumour board, the moot ring, a flyting stage, a hnefatafl board, the mosaic wall (4 stages), the trophy fish, the bench.", "~3"], ["critters", "New creatures and sprites", "The hidden-folk thief family, Freya’s two cats, the white stag, the runaway foal, the forge-fly, the lantern-moth, the brass bird.", "~2"], ["scenes", "Story moments", "Oswin turning a tankard up; Corr and Ilsa at the lighthouse; the taste-off on the Green; the celebration show.", "~4 (panels)"], ["minigame", "Mini-game art", "Flyting cards, hnefatafl pieces, fish, rods, race flags.", "~2"]]};
